# R | Atividades01_02.R | executar na raiz de aprendizado-estatistico.
source("estrutura/codigos/2026-09-15-appa-PrepararBaseSinistros.R", encoding = "UTF-8") # Carrega o banco completo e o recorte de boletins.
out <- "estrutura/resultados/exploratoria"; dir.create(out, recursive = TRUE, showWarnings = FALSE) # Organiza o diagnostico da base.
dic <- data.frame(coluna = names(dados), tipo_R = vapply(dados, function(x) class(x)[1], character(1)), distintos = vapply(dados, function(x) length(unique(x)), integer(1)), ausentes = colSums(is.na(dados))) # Mede estrutura, cardinalidade e faltantes.
write.csv(dic, file.path(out, "01-dicionario-diagnostico.csv"), row.names = FALSE, fileEncoding = "UTF-8") # Complementa o dicionario descritivo existente.
data_evento <- as.Date(boletins$data_sinistro, "%d/%m/%Y"); mes <- format(data_evento, "%Y/%m") # Interpreta o calendario.
hora <- suppressWarnings(as.numeric(substr(boletins$hora_sinistro, 1, 2))) # Extrai hora para descrever, sem usa-la para prever pico.
mensal <- aggregate(rep(1L, nrow(boletins)), list(mes = mes), sum); names(mensal)[2] <- "sinistros" # Conta eventos mensais.
write.csv(mensal, file.path(out, "02-contagens-mensais.csv"), row.names = FALSE) # Registra a serie observada.
fig <- function(pasta, nome, expr) { dir.create(file.path(out, pasta), showWarnings = FALSE); png(file.path(out, pasta, paste0(nome, ".png")), width = 1150, height = 800, res = 120); par(mar = c(5, 5, 4, 2)); force(expr); dev.off() } # Exporta uma figura por pergunta.
barras <- function(x, titulo, maximo = 15) { t <- sort(table(x), decreasing = TRUE); t <- head(t, maximo); par(mar = c(11, 5, 4, 2)); barplot(t, las = 2, col = "steelblue", main = titulo, ylab = "Boletins") } # Mantem rótulos legiveis e informa a unidade.
fig("02a", "01-fatais-histograma", { hist(boletins$qtd_gravidade_fatal, breaks = seq(-.5, max(boletins$qtd_gravidade_fatal) + .5, 1), main = "Distribuicao de vitimas fatais por boletim", xlab = "Vitimas fatais", ylab = "Boletins", col = "steelblue") }) # Mostra a concentracao em zero.
fig("02a", "02-fatais-tipo-via", { boxplot(qtd_gravidade_fatal ~ tipo_via, boletins, main = "Vitimas fatais por tipo de via", xlab = "Tipo de via", ylab = "Vitimas por boletim", col = "lightblue") }) # Compara distribuicoes sem atribuir causa.
fig("02a", "03-sinistros-mes", { par(mar = c(8, 5, 4, 2)); plot(seq_len(nrow(mensal)), mensal$sinistros, type = "b", xaxt = "n", xlab = "", ylab = "Boletins", main = "Sinistros por mes no recorte"); axis(1, seq_len(nrow(mensal)), mensal$mes, las = 2, cex.axis = .8) }) # Evita confundir mes com amostragem irregular.
fig("02a", "04-tipos-sinistro", barras(boletins$tp_sinistro_primario, "Tipos de sinistro registrados")) # Identifica categorias frequentes.
fig("02a", "05-fatais-turno", { boxplot(qtd_gravidade_fatal ~ turno, boletins, main = "Gravidade por turno", xlab = "Turno", ylab = "Vitimas fatais", col = "lightblue") }) # Separa frequencia de gravidade.
fig("02a", "06-municipios", barras(boletins$municipio, "Quinze municipios com mais boletins")) # Explicita que a contagem nao ajusta populacao.
fig("02a", "07-veiculos", { hist(boletins$veiculos, breaks = 40, xlim = c(0, quantile(boletins$veiculos, .999)), col = "steelblue", main = "Veiculos por boletim (eixo ate percentil 99,9)", xlab = "Veiculos", ylab = "Boletins") }) # Mostra a distribuicao com cauda longa.
fig("02a", "08-proporcao-fatal-via", { t <- aggregate(fatal ~ tipo_via, boletins, mean); barplot(t$fatal, names.arg = t$tipo_via, col = "steelblue", main = "Proporcao de boletins fatais por tipo de via", ylab = "Fracao de boletins") }) # Distingue proporcao entre registros de risco por trafego.
set.seed(1); amostra <- boletins[sample(nrow(boletins), 5000), ] # Limita apenas a dispersao visual, sem alterar os calculos agregados.
fig("02a", "09-veiculos-fatais", { plot(jitter(amostra$veiculos), jitter(amostra$qtd_gravidade_fatal), pch = 16, cex = .4, col = rgb(0, 0, 0, .1), xlab = "Veiculos (jitter visual)", ylab = "Vitimas fatais (jitter visual)", main = "Amostra de 5.000 boletins") }) # Torna sobreposicoes visiveis sem inventar observacoes.
fig("02a", "10-regioes", barras(boletins$regiao_administrativa, "Contagens por regiao, sem ajuste por populacao", 20)) # Explicita o denominador ausente.
fig("02a", "11-sinistros-hora", { plot(0:23, as.numeric(table(factor(hora, levels = 0:23))), type = "h", lwd = 5, col = "steelblue", xlab = "Hora", ylab = "Boletins", main = "Distribuicao horaria dos sinistros") }) # Exibe a motivacao temporal do projeto.
fig("02a", "12-mes-turno", { z <- table(mes, boletins$turno); par(mar = c(8, 9, 4, 2)); image(seq_len(nrow(z)), seq_len(ncol(z)), z, axes = FALSE, xlab = "", ylab = "", col = hcl.colors(30, "Blues"), main = "Contagem por mes e turno"); axis(1, seq_len(nrow(z)), rownames(z), las = 2, cex.axis = .7); axis(2, seq_len(ncol(z)), colnames(z), las = 2, cex.axis = .8) }) # Mostra sazonalidade com unidades explicitas.
sp <- boletins[boletins$tipo_via == "VIAS URBANAS", ] # Define um recorte substantivo para a analise segmentada.
fig("02b", "01-urbano-fatais", { hist(sp$qtd_gravidade_fatal, breaks = seq(-.5, max(sp$qtd_gravidade_fatal) + .5, 1), col = "steelblue", main = "Vias urbanas: vitimas fatais por boletim", xlab = "Vitimas fatais", ylab = "Boletins") }) # Repete a distribuicao no segmento.
fig("02b", "02-urbano-turnos", barras(sp$turno, "Vias urbanas: contagens por turno")) # Compara horarios dentro do mesmo segmento.
fig("02b", "03-modais", { z <- colSums(sp[c("qtd_pedestre", "qtd_bicicleta", "qtd_motocicleta", "qtd_automovel", "qtd_onibus", "qtd_caminhao")]); par(mar = c(9, 5, 4, 2)); barplot(z, las = 2, col = "steelblue", main = "Vias urbanas: modais registrados", ylab = "Participacoes registradas") }) # Mantem a unidade de participacao, nao eventos unicos.
fig("02b", "04-medias-modais-fatalidade", { z <- aggregate(cbind(qtd_motocicleta, qtd_automovel, qtd_pedestre) ~ fatal, sp, mean); mat <- t(as.matrix(z[, -1])); barplot(mat, beside = TRUE, names.arg = c("Nao fatal", "Fatal"), col = c("steelblue", "orange", "gray50"), main = "Vias urbanas: media de participantes por boletim", ylab = "Media"); legend("topright", rownames(mat), fill = c("steelblue", "orange", "gray50")) }) # Compara perfil dos boletins sem interpretar como efeito causal.
fig("02b", "05-hora-fatal-naofatal", { h <- suppressWarnings(as.numeric(substr(sp$hora_sinistro, 1, 2))); z <- table(factor(h, levels = 0:23), factor(sp$fatal, levels = 0:1)); z <- sweep(z, 2, colSums(z), "/"); matplot(0:23, z, type = "l", lwd = 2, lty = 1, col = c("steelblue", "firebrick"), main = "Vias urbanas: perfil horario por gravidade", xlab = "Hora", ylab = "Fracao dos boletins do grupo"); legend("topright", c("Nao fatal", "Fatal"), col = c("steelblue", "firebrick"), lty = 1) }) # Normaliza cada grupo para nao confundir tamanho e perfil.
write.csv(data.frame(n_bruto = nrow(dados), colunas = ncol(dados), boletins = nrow(boletins), vias_urbanas = nrow(sp)), file.path(out, "auditoria.csv"), row.names = FALSE) # Registra os tamanhos de cada recorte.
